	bg := lipgloss.Color("#1e1e2e")

	t.Run("TrueColor keeps the exact colour", func(t *testing.T) {
		got := terminalBackground(colorprofile.TrueColor, bg)
		if got == nil || theme.Hex(got) != "#1e1e2e" {
